"""Generate Kentucky's edition from shared UI and independently reviewed state data."""
import copy
import json
import re
from pa_edition import BASE, replace_line


def kentucky_resources(root, ohio):
    ids = json.loads((root / 'data/public/federal-resource-ids.json').read_text())
    by_id = {r['program_id']: r for r in ohio}
    shared = []
    for id in ids:
        r = copy.deepcopy(by_id[id])
        r.update(service_area=['National'], state='shared')
        shared.append(r)
    return (shared + json.loads((root / 'data/public/ky-programs.json').read_text())
            + json.loads((root / 'data/public/ky-regional-referrals.json').read_text()))


def make_ky(html, resources, counties):
    html = replace_line(html, 'const DATA=', 'const DATA=[];')
    html = replace_line(html, 'const COUNTIES=', 'const COUNTIES=[];')
    html = html.replace('Ohio', 'Kentucky').replace('All 88', 'All 120').replace('all 88', 'all 120')
    html = html.replace('<option value="OH">Kentucky</option>', '<option value="OH">Ohio</option>')
    html = html.replace('Choose an Kentucky county', 'Choose a Kentucky county')
    html = html.replace("const STATE='OH';", "const STATE='KY';")
    # Ohio is a Kentucky county, never a statewide service-area synonym here.
    html = replace_line(html, 'const national=', "const national=a=>['statewide','national','federal'].includes(a.toLowerCase());")
    html = html.replace('href="' + BASE + '"', 'href="' + BASE + 'ky.html"').replace('property="og:url" content="' + BASE + '"', 'property="og:url" content="' + BASE + 'ky.html"')
    html = html.replace('assets/share-preview.png', 'assets/vhg-logo.png').replace('content="1200"', 'content="715"').replace('content="630"', 'content="715"')
    html = html.replace('href="share.html"', 'href="share-ky.html"')
    html = html.replace('href="prototype-data.json"', 'href="data/public/kentucky-resources.json"').replace('href="data/public/ohio-county-veterans-offices.json"', 'href="data/public/kentucky-county-veterans-offices.json"')
    html = html.replace('county veterans offices', 'regional veterans referrals').replace('county veterans office', 'regional veterans referral')
    html = html.replace('Find a county office', 'Find a county’s KDVA contacts')
    html = html.replace('Browse contacts for all 120 regional veterans referrals', 'Browse regional veterans contacts for all 120 counties')
    html = html.replace('Most phones come from Kentucky AMVETS’ 2025–2026 directory.', 'Veterans contacts come from KDVA’s county-to-regional-representative directory. Multiple listed representatives and Fort Campbell scope are preserved.')
    html = html.replace('Statewide edition · Updated', 'Kentucky edition · Updated')
    html = html.replace('Kentucky’s waiver rule specifies proposal and approval requirements; VA and other funders have their own processes.', 'Ask your Kentucky waiver case manager or funding administrator about assessment, written approval, owner consent and accepted providers.')
    html = html.replace('https://codes.ohio.gov/ohio-administrative-code/rule-5160-44-13', 'https://www.chfs.ky.gov/agencies/dms/dca/pages/hcb-waiver.aspx').replace('Kentucky home modification authorization and provider rules', 'Kentucky HCB waiver services and application requirements')
    html = re.sub(r'<div class="coverage notice">.*?</div>', '<div class="coverage notice"><strong>Kentucky coverage:</strong> KDVA regional veterans representatives, matched aging contacts, district ombudsmen and Hart-Supported Living coordinators for all 120 counties. These services use separate county maps. Multiple KDVA contacts and the Fort Campbell assignment are labeled. Local posts, repair providers and funding availability are still being researched.</div>', html, count=1)
    priority = ['ky-claims','ky-adrc','ky-homecare','ky-hcb','ky-ship','ky-ombudsman','ky-at','ky-rampup','ky-hart','r02-aid-attendance-housebound','r02-va-pension','r02-survivors-pension','r02-va-health-enrollment','va-accredited-help']
    routes = dict(
        benefits=['r02-aid-attendance-housebound','r02-va-pension','r02-disability-increase','r02-pension-medicaid-rule','r02-survivors-pension','r02-dic','ky-claims','ky-ship','ky-homeless','va-accredited-help'],
        survivors=['r02-survivors-pension','r02-dic','r02-aid-attendance-housebound','r02-va-burial','ky-claims','va-accredited-help','nara-discharge-records'],
        care=['r02-va-health-enrollment','va-location-finder','r02-va-cnh','r02-va-clc','r02-general-caregiver','r02-family-caregiver','r02-hospice','r02-palliative','ky-homes','ky-hcb','ky-homecare','ky-caregiver'],
        rights=['ky-ombudsman','ky-rights','ky-adrc'],
        local=['ky-adrc','ky-homecare','ky-hcb','ky-caregiver','ky-at','ky-hart','ky-rampup'],
        housing=['va-housing-help','nara-discharge-records','va-location-finder','va-accredited-help','ky-homeless','ky-adrc'])
    topics = dict(daily=['ky-adrc','ky-homecare','ky-hcb','ky-caregiver'],accessibility=['ky-adrc','ky-hcb','ky-hart','ky-at','ky-rampup','ky-at-finance','ky-rights'],vision=['ky-blind','ky-at'],hearing=['ky-relay','ky-hearing','ky-at'],memory=['alz-dementia-support','ky-caregiver','ky-adrc'],costs=['ky-ship','ky-adrc','ky-hcb','ky-homecare'],rights=['ky-rights','ky-ombudsman','ky-adrc'])
    for name,value in [('priority',priority),('routes',routes),('seniorTopics',topics)]:
        html = replace_line(html, 'const '+name+'=', 'const '+name+'='+json.dumps(value)+';')
    html = replace_line(html, 'routes.accessibility=', "routes.accessibility=['va-hisa','va-sah','va-sha','va-tra','ky-hcb','ky-hart','ky-at','ky-at-finance','ky-rampup','ky-adrc','ky-homecare','ky-rights','va-location-finder',...DATA.filter(x=>['aging_agency','supported_living'].includes(x.regional_role)).map(x=>x.program_id)];")
    html = replace_line(html, 'routes.seniors=', "routes.seniors=[...new Set(Object.values(seniorTopics).flat()),...DATA.filter(x=>x.regional_role).map(x=>x.program_id),'cms-care-compare'];")
    html = replace_line(html, 'function seniorTopicIDs(', "function seniorTopicIDs(topic){const ids=seniorTopics[topic]||routes.seniors;return [...ids,...(['daily','costs','accessibility','memory'].includes(topic)?regionalIDs('aging_agency'):[]),...(topic==='rights'?regionalIDs('ombudsman'):[]),...(topic==='accessibility'?regionalIDs('supported_living'):[])]}")
    for prefix,text in [('function officeCard(',OFFICE_JS),('function renderOfficeList()',OFFICE_LIST_JS),('function renderCounty()',COUNTY_JS),('function renderSeniorGuide()',SENIOR_JS),('function renderAccessibility()',ACCESS_JS),('function audience(',AUDIENCE_JS)]:
        html = replace_line(html, prefix, text)
    html = html.replace(OFFICE_JS, CONTACT_JS+'\n'+OFFICE_JS)
    for name,value in [('DATA',resources),('COUNTIES',counties)]:
        html = replace_line(html, 'const '+name+'=', 'const '+name+'='+json.dumps(value,ensure_ascii=True).replace('<','\\u003c')+';')
    return html

CONTACT_JS = """function veteransContactsHTML(c){return c.representatives.map(r=>'<p><strong>'+esc(r.name)+' · KDVA region '+esc(r.region)+(r.service_scope?' · '+esc(r.service_scope):'')+'</strong><br>'+phoneLink(r.phone)+'</p>').join('')} function countyContactsHTML(county,role){const contacts=DATA.filter(x=>x.regional_role===role&&x.service_area.includes(county));return contacts.length?contacts.map(x=>'<p><strong>'+esc(x.organization)+'</strong><br>'+phoneLink(x.public_contact.phone)+'</p><p class="meta"><a href="'+esc(x.official_url)+'" target="_blank" rel="noopener">Published contact source</a> · '+esc(labels[x.verification.record_status])+' · '+esc(x.verification.last_reviewed_on)+'</p>').join(''):'<p>Choose a county above for matched regional contacts.</p>'}"""
OFFICE_JS = """function officeCard(c){return `<article class="office-card"><span class="badge">KDVA regional benefits representatives</span><h2>${esc(c.county)} County</h2>${veteransContactsHTML(c)}<p>Ask for benefits screening, accredited claims help and appointment options. Confirm which representative handles your situation.</p><p class="small">${esc(c.note)}</p><p class="meta">Phones published in KDVA’s official county directory · Reviewed ${esc(c.reviewed_on)}</p><div class="links"><a href="${esc(sourceURL(c))}" target="_blank" rel="noopener noreferrer">KDVA contact source ↗</a></div></article>`}"""
OFFICE_LIST_JS = """function renderOfficeList(){const q=$('office-search').value.toLowerCase().trim();const rows=COUNTIES.filter(c=>c.county.toLowerCase().includes(q));$('office-list').innerHTML=rows.map(c=>`<div class="office-row"><button data-county="${esc(c.county)}">${esc(c.county)} County</button>${veteransContactsHTML(c)}<p><a href="${esc(sourceURL(c))}" target="_blank" rel="noopener noreferrer">KDVA regional directory ↗</a></p></div>`).join('')||'<p>No matching county. Try a shorter name.</p>';document.querySelectorAll('[data-county]').forEach(b=>b.onclick=()=>{$('county').value=b.dataset.county;render();$('county-start').scrollIntoView({behavior:'smooth'})})}"""
COUNTY_JS = """function renderCounty(){$('print-handoff-status').textContent='';const c=COUNTIES.find(c=>c.county===$('county').value);$('print-county').textContent=c?c.county+' County, Kentucky':'Kentucky statewide resources';if(!c){$('county-panel').innerHTML='<p class="meta">Choose a county for KDVA regional representatives, aging contacts, district ombudsman support and a printable handoff.</p>';return}$('county-panel').innerHTML='<div class="contact-grid">'+officeCard(c)+'<article><h2>More help in '+esc(c.county)+' County</h2><h3>Aging and community support</h3>'+countyContactsHTML(c.county,'aging_agency')+'<p>Ask about meals, transport, caregiving and support at home. Military service is not required.</p><h3>Local ombudsman: care concerns and resident rights</h3>'+countyContactsHTML(c.county,'ombudsman')+'<p>Give the facility county and describe the resident’s wishes. State ombudsman routing: '+phoneLink('800-372-2991')+'. For immediate danger, call 911.</p><h3>Hart-Supported Living coordinator</h3>'+countyContactsHTML(c.county,'supported_living')+'<p>Ask about individualized disability supports and the current application and funding process.</p><p class="meta">Ask about intake, eligibility and availability when you call.</p></article></div>'}"""
SENIOR_JS = """function renderSeniorGuide(){const active=route==='seniors';$('seniors-guide').hidden=!active;$('community-guide').hidden=route!=='community';$('county-panel').hidden=['accessibility','seniors','community'].includes(route);if(active){$('county-title').textContent='Choose your Kentucky county';$('county-intro').textContent='Find your regional aging contact and district ombudsman. Military service is not required.'}if(route==='community'){$('county-title').textContent='Find Kentucky community connections';$('county-intro').textContent='Use official post locators while local post contacts are being researched.'}if(!active)return;const county=$('county').value;$('seniors-contact').innerHTML='<h3>Start with your aging and disability contact</h3>'+countyContactsHTML(county,'aging_agency')+'<p><strong>Statewide aging and disability routing</strong><br>'+phoneLink('877-925-0037')+'</p><h3>Long-term-care concerns and resident rights</h3>'+countyContactsHTML(county,'ombudsman')+'<p>Describe the need and ask for the next referral. Aging and Medicaid programs have separate eligibility requirements.</p>';const topic=$('senior-topic').value;const guidance={daily:'Ask about meals, transport, personal care and caregiver support. Homecare serves eligible people age 60+; Medicaid HCB has separate financial, disability or age, and level-of-care requirements.',accessibility:'Describe the access barrier. Ask about HCB environmental or minor home adaptations and Hart-Supported Living. KATS offers equipment trials; RampUp! KY offers temporary portable ramps for up to six months, subject to stock. Neither route guarantees a permanent ramp or installation.',vision:'Ask Kentucky IL/OIB services about a needs assessment, adaptive daily-living training and low-vision aids. Confirm which program fits the resident.',hearing:'Dial 711 for Kentucky Relay. Ask KCDHH about communication support and TAP equipment; the published TAP route requires at least one year of Kentucky residence. Hearing-aid funding is not guaranteed.',memory:'Contact the Alzheimer’s Association for dementia support. Ask the aging agency about family caregiver support, respite and services at home; seek clinical evaluation for new memory concerns.',costs:'Kentucky SHIP offers free Medicare counseling at 877-293-7447, menu option 2. Ask about coverage and savings programs. Medicaid support requires separate screening.',rights:'Contact the district long-term-care ombudsman for facility resident concerns and Kentucky Protection and Advocacy for disability rights. Confirm intake priorities and the follow-up process.'};$('senior-guidance').innerHTML='<strong>'+(topic?'Your next step':'Choose a need, then make a referral')+'</strong><p>'+esc(guidance[topic]||'Choose a need to narrow the referrals. Military service is not required for these routes. Confirm eligibility and availability with the provider.')+'</p>'}"""
AUDIENCE_JS = """function audience(x){if(/survivors|r02-dic/.test(x.program_id))return 'Surviving spouses and other qualifying survivors';if(/aid-attendance/.test(x.program_id))return 'Qualifying veterans and survivors who need daily help';if(x.program_id==='ky-homecare')return 'Eligible adults age 60+ at risk of institutional care';if(x.program_id==='ky-hcb')return 'People age 65+ and/or with a physical disability who meet Medicaid and level-of-care requirements';if(/ombudsman/.test(x.program_id))return 'Residents of nursing homes, personal care homes and family care homes';if(/nara/.test(x.program_id))return 'Veterans and eligible records requesters';return null}"""
ACCESS_JS = """function renderAccessibility(){const active=route==='accessibility';$('accessibility-guide').hidden=!active;$('county-panel').hidden=active;$('county-title').textContent=active?'Choose where help is needed':'Your first regional contact';$('county-intro').textContent=active?'Choose a Kentucky county for regional referral contacts.':'KDVA regional representatives can help with benefits and referral screening. Confirm the current assignment and appointment options.';if(!active)return;const veteran=$('access-veteran').value,home=$('access-home').value,coverage=$('access-waiver').value,county=$('county').value,office=COUNTIES.find(c=>c.county===county),va=veteran==='yes',newHome=home==='new';const primary=coverage==='waiver'?'Your waiver case manager':va?(newHome?'VA adapted housing team':'VA Prosthetics and your care team'):'Kentucky aging and disability counseling';const action=coverage==='waiver'?'Ask for an access assessment and written authorization through your service plan.':va?(newHome?'Ask about SAH/SHA eligibility and housing project review. HISA excludes new construction.':'Ask for clinical review and the HISA application process.'):'Ask which local agency can assess the barrier and screen for Kentucky support.';const contact=coverage==='waiver'?'<p>Use your case manager’s direct number. Ask which program can authorize the proposed change.</p>':va?'<p><a class="contact-action" href="https://www.va.gov/find-locations/?facilityType='+(newHome?'benefits':'health')+'" target="_blank" rel="noopener">Find your VA '+(newHome?'benefits office':'medical facility')+'</a></p>':'<p>'+phoneLink('877-925-0037')+'</p>';$('access-first').innerHTML='<article class="first-call"><span class="badge">Start here'+(county?' · '+esc(county)+' County, KY':'')+'</span><h3>'+esc(primary)+'</h3><p>'+esc(action)+'</p>'+contact+'</article><article><h3>Need help getting connected?</h3>'+(office?'<h4>KDVA regional benefits representatives</h4>'+veteransContactsHTML(office)+'<p class="meta"><a href="'+esc(sourceURL(office))+'" target="_blank" rel="noopener">KDVA published contact source</a></p>':'<p>Choose a county above for KDVA referral help.</p>')+countyContactsHTML(county,'aging_agency')+'<h4>Hart-Supported Living coordinator</h4>'+countyContactsHTML(county,'supported_living')+'<p><strong>Statewide aging and disability routing</strong><br>'+phoneLink('877-925-0037')+'</p></article>';$('access-steps').innerHTML='<h3>Your next three steps</h3><ol><li><strong>Make the first call.</strong> '+esc(action)+' Ask who handles follow-up.</li><li><strong>Prepare requested documents.</strong> '+(va&&!newHome&&coverage!=='waiver'?'For HISA, gather the prescription, Form 10-0103, owner permission, itemized estimate and before photograph. <a href="#hisa-checklist" id="open-hisa">Open the HISA checklist</a>.':'Ask about assessment, disability documentation, residency, income, owner consent and estimate requirements.')+'</li><li><strong>Confirm approval and remaining costs.</strong> Ask who approves work, which providers are accepted and how uncovered costs are handled.</li></ol>';const box=(title,body)=>'<article><h3>'+title+'</h3>'+body+'</article>';const parts=[];if(veteran!=='no'){parts.push(box('Veteran route: VA clinical review','<p>Ask Prosthetic and Sensory Aids Service about HISA. HISA excludes new construction; SAH/SHA have separate qualifying disability and ownership rules.</p><p><a href="https://www.va.gov/find-locations/?facilityType=health" target="_blank" rel="noopener">Find your VA medical facility</a></p>'));if(home==='family')parts.push(box('Temporary family home: ask about TRA','<p>Ask VA whether TRA applies; it requires SAH or SHA eligibility and temporary residence in a family member’s home.</p>'))}parts.push(box('Kentucky: assessment and service planning','<p>Aging and disability routing '+phoneLink('877-925-0037')+' can connect you to local screening. HCB may cover environmental or minor home adaptations for approved participants; Medicaid enrollment alone does not establish coverage. Homecare offers locally available services for eligible adults age 60+.</p>'));parts.push(box('Individualized community living supports','<p>Ask the county-matched Hart-Supported Living coordinator about an application, appropriate supports and the current funding cycle.</p>'+countyContactsHTML(county,'supported_living')));parts.push(box('Equipment trials and temporary ramps','<p>KATS Network '+phoneLink('800-327-5287')+' offers equipment trials and loans. RampUp! KY loans portable ramps for up to six months, subject to stock and suitability; it does not build ramps. Applicants arrange pickup, return, setup and installation. Ask about fees and loan terms.</p>'));if(coverage==='waiver')parts.push(box('Coordinate with your service plan','<p>Ask your waiver case manager what can be authorized through your plan. Confirm assessment and written approval before arranging work.</p>'));if(home==='new')parts.push(box('Unfinished or new construction','<p>HISA excludes new construction. Ask each administrator whether the proposed work qualifies before requesting estimates or committing funds.</p>'));if(home==='facility')parts.push(box('Returning home: coordinate before discharge','<p>Ask the discharge planner, HCB waiver intake and your case manager about assessment, care needs and a safe community transition plan. A referral does not guarantee enrollment or a home modification.</p>'));if(home==='rent')parts.push(box('Rented home: confirm owner responsibilities','<p>Arrange owner permission and clarify any existing duty to provide accessibility changes. HISA requires notarized owner permission for renters; other programs have their own rules.</p>'));$('access-routing').innerHTML=parts.join('');const checklistLink=$('open-hisa');if(checklistLink)checklistLink.onclick=()=>{$('hisa-checklist').open=true};}"""
